using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Drawing;using System.Drawing.Imaging;using EnhancedZune;using ZuneRestoration;
class Mapping {public string id=null,name=null;}
class Tests {
 static string root,stock;static Mapping[] map;static List<string> passed=new List<string>();static void Check(bool a,string s){if(!a)throw new Exception(s);}static void Pass(string s){passed.Add(s);Console.WriteLine("PASS "+s);}static void Fails(Action a,string s){bool failed=false;try{a();}catch{failed=true;}Check(failed,s);}
 static string New(string name,Manifest m){string p=Path.Combine(root,name);Directory.CreateDirectory(p);foreach(string n in m.dependencies.Select(x=>x.name).Concat(m.files.Where(x=>x.kind=="delta").Select(x=>x.name))){Mapping row=map.Single(x=>x.name==n);File.Copy(Path.Combine(stock,row.id),Path.Combine(p,n));}File.WriteAllText(Path.Combine(p,"user-data.marker"),"do not alter");return p;}
 static void Original(string p,Manifest m){Check(Engine.State(p,m)=="Original","Expected exact original state");Check(File.ReadAllText(Path.Combine(p,"user-data.marker"))=="do not alter","User marker changed");}
 static void Quiet(string s){}
 static int Main(string[] args){try{root=Path.GetFullPath(args[0]);stock=Path.GetFullPath(args[1]);Directory.CreateDirectory(root);Engine.Testing=true;Engine.TestRoot=root;map=new JavaScriptSerializer().Deserialize<Mapping[]>(File.ReadAllText(args[2]));using(Bundle b=new Bundle()){
  string p=New("normal",b.M);Original(p,b.M);string backup=Engine.Install(p,b,Quiet);Check(Engine.State(p,b.M)=="Enhanced","Install failed");foreach(Entry e in b.M.files)Check(Engine.FileHash(Path.Combine(p,e.name))==e.patched_sha256,"Reconstructed hash differs");Pass("All twelve components reconstruct exactly from verified stock inputs");string repeated=Engine.Install(p,b,Quiet);Check(repeated==backup,"Repeat installed again");Pass("Repeat installation is a verified no-op");Engine.Restore(p,backup,b,Quiet);Original(p,b.M);Pass("Normal restore returns original files and removes only the six added components");
  for(int i=0;i<b.M.files.Length;i++){p=New("failure-"+i,b.M);int at=i;Fails(()=>Engine.Install(p,b,Quiet,at),"Failure injection missing");Original(p,b.M);}Pass("Injected failures at every replacement boundary automatically restore originals");
  p=New("unknown",b.M);string file=Path.Combine(p,"UIXrender.dll");byte[] raw=File.ReadAllBytes(file);raw[512]^=1;File.WriteAllBytes(file,raw);string hash=Engine.FileHash(file);Fails(()=>Engine.Install(p,b,Quiet),"Unknown modification accepted");Check(Engine.FileHash(file)==hash,"Unknown file was overwritten");Pass("Unknown modifications rejected without replacement");
  p=New("dependencies",b.M);file=Path.Combine(p,"ZuneService.dll");raw=File.ReadAllBytes(file);raw[512]^=1;File.WriteAllBytes(file,raw);Fails(()=>Engine.Install(p,b,Quiet),"Modified service accepted");Pass("Modified service / dependency rejected before enhancement writes");
  p=New("repair",b.M);backup=Engine.Install(p,b,Quiet);File.Delete(Path.Combine(p,"ZuneScalingSettings.dll"));File.Delete(Path.Combine(p,"ZuneLocalArtistPhotos.dll"));File.Delete(Path.Combine(p,"UIX.dll"));Engine.Repair(p,b,Quiet);Check(Engine.State(p,b.M)=="Enhanced","Missing-component repair failed");Engine.Restore(p,backup,b,Quiet);Original(p,b.M);Pass("Repair rebuilds missing helper and modified Microsoft component from verified backup");
  p=New("damaged-backup",b.M);backup=Engine.Install(p,b,Quiet);file=Path.Combine(backup,"UIX.dll");raw=File.ReadAllBytes(file);raw[512]^=1;File.WriteAllBytes(file,raw);Fails(()=>Engine.Restore(p,backup,b,Quiet),"Damaged backup accepted");Check(Engine.State(p,b.M)=="Enhanced","Damaged-backup refusal changed target");Pass("Damaged recovery backup rejected before restoring any file");
  p=New("later-change",b.M);backup=Engine.Install(p,b,Quiet);file=Path.Combine(p,"UIX.dll");raw=File.ReadAllBytes(file);raw[512]^=1;File.WriteAllBytes(file,raw);hash=Engine.FileHash(file);Fails(()=>Engine.Restore(p,backup,b,Quiet),"Later change overwritten");Fails(()=>Engine.Repair(p,b,Quiet),"Repair overwrote later change");Check(Engine.FileHash(file)==hash,"Later file changed");Pass("Repair and restore protect unknown later modifications");
  p=New("interrupted",b.M);backup=Engine.Install(p,b,Quiet);Journal j=Engine.Load(backup);j.status="Installing";Engine.Save(backup,j);File.Copy(Path.Combine(backup,"UIX.dll"),Path.Combine(p,"UIX.dll"),true);Fails(()=>Engine.Install(p,b,Quiet),"Interrupted install ignored");Engine.Restore(p,backup,b,Quiet);Original(p,b.M);Pass("Persisted interrupted transaction survives a fresh read and recovers a mixed state");
  p=New("custom-background",b.M);backup=Engine.Install(p,b,Quiet);file=Path.Combine(p,"ZuneShellResources.dll");Check(Slots.ValidEnhanced(file,b.M),"Canonical resource fingerprint failed: "+Slots.LastFailure);byte[] image;using(Bitmap bmp=new Bitmap(256,144)){using(Graphics g=Graphics.FromImage(bmp))g.Clear(Color.SteelBlue);using(MemoryStream ms=new MemoryStream()){bmp.Save(ms,ImageFormat.Png);image=ms.ToArray();}}string staged=Path.Combine(p,"custom.new");BackgroundResources.Build(file,staged,new[]{1,-1,-1},new[]{image,null,null});File.Replace(staged,file,null);Check(Slots.ValidEnhanced(file,b.M),"User custom background incorrectly rejected");Check(Engine.State(p,b.M)=="Enhanced","Custom slot broke installed identity");hash=Engine.FileHash(file);Engine.Install(p,b,Quiet);File.Delete(Path.Combine(p,"ZuneScalingSettings.dll"));Engine.Repair(p,b,Quiet);Check(Engine.FileHash(file)==hash,"Repair removed user's custom background");Engine.Restore(p,backup,b,Quiet);Original(p,b.M);Check(Engine.FileHash(Path.Combine(backup,"custom-backgrounds-before-restore.dll"))==hash,"Custom backgrounds not archived on restore");Check(Engine.FileHash(Path.Combine(backup,"CustomBackground1.png"))==Engine.Hash(image),"Exported background PNG differs");Pass("Custom background edits recognized; reinstall/repair preserve them; restore archives them");
  p=New("interrupted-recovery",b.M);backup=Engine.Install(p,b,Quiet);File.Delete(Path.Combine(p,"UIX.dll"));File.Delete(Path.Combine(p,"ZuneScalingSettings.dll"));j=Engine.Load(backup);j.status="Restoring";Engine.Save(backup,j);Engine.Restore(p,backup,b,Quiet);Original(p,b.M);Pass("Interrupted repair/recovery resumes from a persisted journal with missing components");
  using(Bundle old=new Bundle(false,"legacy-payload.zip")){
   p=New("previous-release",old.M);string oldBackup=Engine.Install(p,old,Quiet);Check(Engine.State(p,old.M)=="Enhanced","Legacy fixture not installed");
   Fails(()=>Engine.Install(p,b,Quiet),"Earlier version must request verified restore first");Check(Engine.State(p,old.M)=="Enhanced","Earlier-version refusal changed files");
   Engine.RestoreKnown(p,oldBackup,b,Quiet);Original(p,b.M);string newBackup=Engine.Install(p,b,Quiet);Check(Engine.State(p,b.M)=="Enhanced","Upgrade after legacy restore failed");Engine.RestoreKnown(p,newBackup,b,Quiet);Original(p,b.M);
   Pass("Same new EXE can verify/restore the earlier RC2 backup, then install RC7; old-version refusal is non-destructive");
  }
  p=New("reinstalled-current-helpers",b.M);backup=Engine.Install(p,b,Quiet);foreach(Entry e in b.M.files.Where(x=>x.kind=="delta"))File.Copy(Path.Combine(backup,e.name),Path.Combine(p,e.name),true);Engine.Install(p,b,Quiet);Check(Engine.State(p,b.M)=="Enhanced","Current helper leftovers prevented original reinstall");Pass("Original reinstall with current helper leftovers is recovered through a verified backup");
  p=New("reinstalled-unknown-helper",b.M);backup=Engine.Install(p,b,Quiet);foreach(Entry e in b.M.files.Where(x=>x.kind=="delta"))File.Copy(Path.Combine(backup,e.name),Path.Combine(p,e.name),true);file=Path.Combine(p,"ZuneLocalArtistPhotos.dll");raw=File.ReadAllBytes(file);raw[512]^=1;File.WriteAllBytes(file,raw);var snapshot=b.M.files.ToDictionary(e=>e.name,e=>Engine.FileHash(Path.Combine(p,e.name)));Fails(()=>Engine.Install(p,b,Quiet),"Unknown helper overwritten during reinstall recovery");foreach(var item in snapshot)Check(Engine.FileHash(Path.Combine(p,item.Key))==item.Value,"Reinstall refusal modified "+item.Key);Check(Engine.Load(backup).status=="Installed","Refusal changed recovery journal");Pass("Unknown helper leftovers are protected with no partial cleanup");
  p=New("reinstalled-damaged-backup",b.M);backup=Engine.Install(p,b,Quiet);foreach(Entry e in b.M.files.Where(x=>x.kind=="delta"))File.Copy(Path.Combine(backup,e.name),Path.Combine(p,e.name),true);file=Path.Combine(backup,"UIX.dll");raw=File.ReadAllBytes(file);raw[512]^=1;File.WriteAllBytes(file,raw);snapshot=b.M.files.ToDictionary(e=>e.name,e=>Engine.FileHash(Path.Combine(p,e.name)));Fails(()=>Engine.Install(p,b,Quiet),"Damaged backup accepted during reinstall recovery");foreach(var item in snapshot)Check(Engine.FileHash(Path.Combine(p,item.Key))==item.Value,"Damaged-backup refusal modified "+item.Key);Pass("Damaged backups stop reinstall recovery before deleting any helper");
  string escaped=Path.Combine(Path.GetDirectoryName(root),"outside");Fails(()=>Engine.Guard(escaped),"Test boundary escaped");Pass("Test mutation guard rejects paths outside disposable workspace");
 }
 File.WriteAllText(Path.Combine(root,"results.json"),new JavaScriptSerializer().Serialize(new{status="passed",tests=passed,scope="Isolated file copies only. No original MSI installation, live Zune UI, UAC or Windows reboot test."}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);if(root!=null)File.WriteAllText(Path.Combine(root,"failure.txt"),e.ToString());return 1;}}
}
